#ifndef VELA_RT_H
#define VELA_RT_H

/* Runtime support for C generated by the Vela compiler. Every name here
 * starts with `vela__rt__`, a shape no C name generated from a Vela program can
 * take (see the naming notes in `src/codegen.rs`). */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static inline void vela__rt__show_int(int64_t x) {
    /* `long long` is at least 64 bits everywhere; `long` is 32 bits on Windows. */
    printf("%lld\n", (long long)x);
}

static inline void vela__rt__show_float(double x) {
    /* C libraries print a NaN's sign inconsistently (`-nan` or `nan`). */
    if (isnan(x)) {
        puts("nan");
        return;
    }
    printf("%g\n", x);
}

static inline void vela__rt__show_bool(bool x) {
    printf("%s\n", x ? "true" : "false");
}

static inline void vela__rt__show_text(const char* x) {
    printf("%s\n", x);
}

/* `show` on an empty `maybe`. */
static inline void vela__rt__show_none(void) {
    puts("none");
}

/* `==` on text compares contents. */
static inline bool vela__rt__text_eq(const char* a, const char* b) {
    return strcmp(a, b) == 0;
}

/* Integer arithmetic. An `int` doesn't wrap: an operation whose result doesn't
 * fit in 64 bits, and a division or remainder by zero, stop the program with a
 * message saying where, which `at` gives as "LINE:COL in task 'NAME'". The
 * checks use the C compiler's overflow builtins where it has them, and plain
 * comparisons elsewhere (or when VELA__RT__PORTABLE_ARITHMETIC is defined, which
 * the runtime tests use to test those). */

static inline _Noreturn void vela__rt__int_trap(const char* what, const char* at) {
    fflush(stdout);
    fprintf(stderr, "vela: %s at %s\n", what, at);
    abort();
}

#if defined(__GNUC__) && !defined(VELA__RT__PORTABLE_ARITHMETIC)
#define VELA__RT__OVERFLOW_BUILTINS 1
#else
#define VELA__RT__OVERFLOW_BUILTINS 0
#endif

/* Whether `a + b` overflows; otherwise stores it in `*r`. */
static inline bool vela__rt__add_overflows(int64_t a, int64_t b, int64_t* r) {
#if VELA__RT__OVERFLOW_BUILTINS
    return __builtin_add_overflow(a, b, r);
#else
    if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b)) {
        return true;
    }
    *r = a + b;
    return false;
#endif
}

/* Whether `a - b` overflows; otherwise stores it in `*r`. */
static inline bool vela__rt__sub_overflows(int64_t a, int64_t b, int64_t* r) {
#if VELA__RT__OVERFLOW_BUILTINS
    return __builtin_sub_overflow(a, b, r);
#else
    if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b)) {
        return true;
    }
    *r = a - b;
    return false;
#endif
}

/* Whether `a * b` overflows; otherwise stores it in `*r`. */
static inline bool vela__rt__mul_overflows(int64_t a, int64_t b, int64_t* r) {
#if VELA__RT__OVERFLOW_BUILTINS
    return __builtin_mul_overflow(a, b, r);
#else
    bool overflows;
    if (a > 0) {
        overflows = b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a;
    } else if (a < 0) {
        overflows = b > 0 ? a < INT64_MIN / b : b < 0 && a < INT64_MAX / b;
    } else {
        overflows = false;
    }
    if (overflows) {
        return true;
    }
    *r = a * b;
    return false;
#endif
}

static inline int64_t vela__rt__add(int64_t a, int64_t b, const char* at) {
    int64_t r;
    if (vela__rt__add_overflows(a, b, &r)) {
        vela__rt__int_trap("integer overflow", at);
    }
    return r;
}

static inline int64_t vela__rt__sub(int64_t a, int64_t b, const char* at) {
    int64_t r;
    if (vela__rt__sub_overflows(a, b, &r)) {
        vela__rt__int_trap("integer overflow", at);
    }
    return r;
}

static inline int64_t vela__rt__mul(int64_t a, int64_t b, const char* at) {
    int64_t r;
    if (vela__rt__mul_overflows(a, b, &r)) {
        vela__rt__int_trap("integer overflow", at);
    }
    return r;
}

/* Division truncates toward zero. The one quotient that doesn't fit is
 * INT64_MIN / -1. */
static inline int64_t vela__rt__div(int64_t a, int64_t b, const char* at) {
    if (b == 0) {
        vela__rt__int_trap("division by zero", at);
    }
    if (b == -1 && a == INT64_MIN) {
        vela__rt__int_trap("integer overflow", at);
    }
    return a / b;
}

/* The remainder has the dividend's sign. A remainder always fits: INT64_MIN % -1
 * is 0, which C leaves undefined, so it is computed here. */
static inline int64_t vela__rt__mod(int64_t a, int64_t b, const char* at) {
    if (b == 0) {
        vela__rt__int_trap("remainder of division by zero", at);
    }
    if (b == -1) {
        return 0;
    }
    return a % b;
}

static inline int64_t vela__rt__neg(int64_t a, const char* at) {
    if (a == INT64_MIN) {
        vela__rt__int_trap("integer overflow", at);
    }
    return -a;
}

/* Float remainder (Vela's `%` on floats); the result has the dividend's sign. */
static inline double vela__rt__fmod(double a, double b) {
    return fmod(a, b);
}

/* Regions. A region is an arena: a list of chunks of memory, each handed out
 * front to back, all freed at once when the block that declared the region
 * closes. Allocating is a pointer bump in the newest chunk; see
 * `vela__rt__region_grow` for how chunks are added. */

typedef struct vela__rt__chunk {
    struct vela__rt__chunk* previous;
    size_t size;
    size_t used;
    /* Aligned for any type, so the first allocation needs no padding. */
    _Alignas(max_align_t) unsigned char data[];
} vela__rt__chunk;

typedef struct vela__rt__region {
    vela__rt__chunk* newest;
} vela__rt__region;

/* The initializer of an empty region: `vela__rt__region r[1] = { VELA__RT__REGION_EMPTY };`. */
#define VELA__RT__REGION_EMPTY { NULL }

/* Total sizes of ordinary chunks, header included. */
enum { VELA__RT__CHUNK_FIRST = 4096, VELA__RT__CHUNK_MAX = 1 << 20 };

static inline _Noreturn void vela__rt__out_of_memory(void) {
    fflush(stdout);
    fputs("vela: out of memory\n", stderr);
    abort();
}

/* A new chunk of at least `size` bytes, whose first `size` bytes are taken.
 * Ordinary chunks double in total size (header included, so each malloc is a
 * power of two) from 4 KB up to 1 MB. An allocation larger than half the next
 * ordinary chunk gets a chunk of exactly its size instead, placed behind the
 * newest chunk, which keeps serving small allocations. In an empty region, an
 * allocation that fits the first ordinary chunk goes there, and a larger one
 * gets its own chunk, after which ordinary chunks start again at 4 KB. */
static inline void* vela__rt__region_grow(vela__rt__region* r, size_t size) {
    size_t header = sizeof(vela__rt__chunk);
    size_t total = VELA__RT__CHUNK_FIRST;
    if (r->newest != NULL) {
        size_t previous = r->newest->size + header;
        bool ordinary = previous <= VELA__RT__CHUNK_MAX && (previous & (previous - 1)) == 0;
        if (ordinary) {
            total = previous >= VELA__RT__CHUNK_MAX / 2 ? VELA__RT__CHUNK_MAX : previous * 2;
        }
    }
    size_t capacity = total - header;
    bool own = r->newest != NULL ? size > capacity / 2 : size > capacity;
    if (own) {
        capacity = size;
    }
    if (capacity > SIZE_MAX - header) {
        vela__rt__out_of_memory();
    }
    vela__rt__chunk* chunk = malloc(header + capacity);
    if (chunk == NULL) {
        vela__rt__out_of_memory();
    }
    chunk->size = capacity;
    chunk->used = size;
    if (own && r->newest != NULL) {
        chunk->previous = r->newest->previous;
        r->newest->previous = chunk;
    } else {
        chunk->previous = r->newest;
        r->newest = chunk;
    }
    return chunk->data;
}

/* `size` bytes aligned to `align` (a power of two) in region `r`. */
static inline void* vela__rt__region_alloc(vela__rt__region* r, size_t size, size_t align) {
    vela__rt__chunk* chunk = r->newest;
    if (chunk != NULL) {
        size_t start = (chunk->used + (align - 1)) & ~(align - 1);
        if (start <= chunk->size && size <= chunk->size - start) {
            chunk->used = start + size;
            return chunk->data + start;
        }
    }
    return vela__rt__region_grow(r, size);
}

/* `new T(value) at r`: copies `size` bytes from `value` into region `r`. */
static inline void* vela__rt__new(vela__rt__region* r, const void* value, size_t size, size_t align) {
    void* p = vela__rt__region_alloc(r, size, align);
    memcpy(p, value, size);
    return p;
}

/* Arrays and slices. An index or a slice's bounds out of range stop the
 * program, as does a negative count of items for a slice, with a message saying
 * where, which `at` gives as "LINE:COL in task 'NAME'". Ranges are written as in
 * Vela, `0..4` for the items 0 to 3. */

/* `i`, when it is an index of an array or slice of `len` items. */
static inline int64_t vela__rt__index(int64_t i, int64_t len, const char* at) {
    if (i < 0 || i >= len) {
        fflush(stdout);
        fprintf(stderr, "vela: index %lld is out of range 0..%lld at %s\n", (long long)i, (long long)len, at);
        abort();
    }
    return i;
}

/* Checks the bounds of `xs[from..to]`, where `xs` has `len` items. */
static inline void vela__rt__part(int64_t from, int64_t to, int64_t len, const char* at) {
    if (to < from) {
        fflush(stdout);
        fprintf(stderr, "vela: slice %lld..%lld ends before it starts at %s\n", (long long)from, (long long)to, at);
        abort();
    }
    if (from < 0 || to > len) {
        fflush(stdout);
        fprintf(stderr, "vela: slice %lld..%lld is out of range 0..%lld at %s\n", (long long)from, (long long)to, (long long)len, at);
        abort();
    }
}

/* Room for `len` items of `size` bytes aligned to `align` in region `r`. */
static inline void* vela__rt__region_items(vela__rt__region* r, int64_t len, size_t size, size_t align, const char* at) {
    if (len < 0) {
        fflush(stdout);
        fprintf(stderr, "vela: count %lld is negative at %s\n", (long long)len, at);
        abort();
    }
    if ((uint64_t)len > SIZE_MAX / size) {
        vela__rt__out_of_memory();
    }
    return vela__rt__region_alloc(r, (size_t)len * size, align);
}

/* The items of `new [T]() at r`, which has none: any address will do, as long as
 * it is aligned for any type; nothing is ever read or written there. */
static inline void* vela__rt__no_items(void) {
    static _Alignas(max_align_t) char none[1];
    return none;
}

/* Slices that grow and shrink: `xs.add(…)` and `xs.del(…)`.
 *
 * A slice is its items' address, its length, and its room: a block in a region
 * that `add` made, which holds the slice's items followed by free space. `end`
 * is where the items end (the next item goes there) and `limit` where the block
 * does. A slice made another way (by `new`, or a part of an array) has no room
 * yet, and its first `add` copies its items into one.
 *
 * Only a slice whose items end exactly at `end` adds in place; any other slice
 * sharing the block (an older copy of it, or a part of it) sees a different end
 * and copies its items into a block of its own first, so an `add` never writes
 * over items another slice counts. Taking out the last item of the block gives
 * its space back to the room. Blocks double in size, and a block that ends
 * where its region's newest chunk hands out memory grows in place instead. */

typedef struct vela__rt__room {
    char* end;
    char* limit;
} vela__rt__room;

static inline _Noreturn void vela__rt__empty_trap(const char* at) {
    fflush(stdout);
    fprintf(stderr, "vela: del() on an empty slice at %s\n", at);
    abort();
}

/* Checks that a slice of `len` items has an item to take out with `del()`. */
static inline void vela__rt__not_empty(int64_t len, const char* at) {
    if (len == 0) {
        vela__rt__empty_trap(at);
    }
}

/* Grows `room`, whose block ends where the newest chunk of `r` hands out memory,
 * in place: by `wanted` bytes (the size of its items, so it doubles), or by as
 * many whole items of `size` bytes as the chunk still has. */
static inline void vela__rt__room_extend(vela__rt__region* r, vela__rt__room* room, size_t wanted, size_t size) {
    vela__rt__chunk* chunk = r->newest;
    if (chunk == NULL || room->limit != (char*)chunk->data + chunk->used) {
        return;
    }
    size_t spare = chunk->size - chunk->used;
    size_t more = wanted < size ? size : wanted;
    if (more > spare) {
        more = spare - spare % size;
    }
    chunk->used += more;
    room->limit += more;
}

/* Makes a gap for one item before item `index` (0 to `len`) of a slice with
 * `len` items of `size` bytes aligned to `align` at `items`, whose room is
 * `*room`, and returns the address of the items, which may have moved into a
 * new block of region `r` (then `*room` is that block's). The gap is left for
 * the caller to fill. */
static inline void* vela__rt__items_insert(vela__rt__region* r, void* items, int64_t len, vela__rt__room** room, int64_t index,
                                           size_t size, size_t align) {
    char* old = items;
    size_t n = (size_t)len;
    size_t i = (size_t)index;
    vela__rt__room* own = *room;
    if (own != NULL && old + n * size == own->end) {
        if ((size_t)(own->limit - own->end) < size) {
            vela__rt__room_extend(r, own, n * size, size);
        }
        if ((size_t)(own->limit - own->end) >= size) {
            memmove(old + (i + 1) * size, old + i * size, (n - i) * size);
            own->end += size;
            return old;
        }
    }
    size_t header = (sizeof(vela__rt__room) + align - 1) & ~(align - 1);
    if (n > (SIZE_MAX - header) / size / 2 - 4) {
        vela__rt__out_of_memory();
    }
    size_t capacity = n < 4 ? 4 : 2 * n;
    size_t block_align = align > _Alignof(vela__rt__room) ? align : _Alignof(vela__rt__room);
    char* block = vela__rt__region_alloc(r, header + capacity * size, block_align);
    char* fresh = block + header;
    memcpy(fresh, old, i * size);
    memcpy(fresh + (i + 1) * size, old + i * size, (n - i) * size);
    vela__rt__room* made = (vela__rt__room*)(void*)block;
    made->end = fresh + (n + 1) * size;
    made->limit = fresh + capacity * size;
    *room = made;
    return fresh;
}

/* Closes the gap item `index` of a slice with `len` items of `size` bytes at
 * `items` leaves when it is taken out, moving the items after it down; the
 * slice's length is then one less. */
static inline void vela__rt__items_remove(void* items, int64_t len, vela__rt__room* room, int64_t index, size_t size) {
    char* at = items;
    size_t n = (size_t)len;
    size_t i = (size_t)index;
    memmove(at + i * size, at + (i + 1) * size, (n - i - 1) * size);
    if (room != NULL && at + n * size == room->end) {
        room->end -= size;
    }
}

/* Frees everything allocated in `r`, which is then empty again. */
static inline void vela__rt__region_free(vela__rt__region* r) {
    vela__rt__chunk* chunk = r->newest;
    while (chunk != NULL) {
        vela__rt__chunk* previous = chunk->previous;
        free(chunk);
        chunk = previous;
    }
    r->newest = NULL;
}

/* Placed at the end of every task that returns a value. The checker ensures
 * every path sends, so this is never reached; it keeps C compilers from
 * treating the end of the function as reachable (undefined behavior). */
static inline _Noreturn void vela__rt__missing_send(const char* task) {
    fflush(stdout);
    fprintf(stderr, "vela: task '%s' finished without sending a value\n", task);
    abort();
}

#endif
